package br.com.confirmacao.user.application;import br.com.confirmacao.user.domain.User;import br.com.confirmacao.user.infrastructure.UserRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.UUID;
@Service public class UserManagementService{private final UserRepository users;public UserManagementService(UserRepository u){users=u;}@Transactional(readOnly=true)public Page<User> findAll(Pageable p){return users.findAll(p);}}
